import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  Menu as AriaMenu,
  MenuItem as AriaMenuItem,
  composeRenderProps,
  type MenuItemProps,
  type MenuProps,
  MenuTrigger,
  Popover,
  Separator,
  type SeparatorProps,
} from "react-aria-components";
import { cn } from "./utils";

export { MenuTrigger };

export function Menu<T extends object>({ className, ...props }: MenuProps<T>) {
  return (
    <MenuPopover>
      <MenuContent {...props} className={className} />
    </MenuPopover>
  );
}

export function MenuPopover({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  const reduceMotion = useReducedMotion();
  return (
    <Popover
      {...props}
      data-slot="menu-popover"
      placement={props.placement ?? "bottom start"}
      offset={props.offset ?? 7}
      className={composeRenderProps(className, (className) =>
        cn(
          "min-w-44 motion-safe:transition-opacity motion-safe:duration-150 motion-safe:ease-out motion-safe:data-[exiting]:opacity-0 max-w-[calc(100vw-2rem)] rounded-lg bg-popover p-1.5 text-popover-foreground shadow-[var(--shadow-float)] ring-1 ring-border/70 outline-none",
          className,
        ),
      )}
    >
      {(renderProps) => (
        <motion.div
          initial={
            reduceMotion ? { opacity: 0 } : { opacity: 0, y: -6, scale: 0.98 }
          }
          animate={{ opacity: 1, y: 0, scale: 1 }}
          transition={{ duration: reduceMotion ? 0 : 0.18, ease: "easeOut" }}
        >
          {typeof children === "function" ? children(renderProps) : children}
        </motion.div>
      )}
    </Popover>
  );
}

export function MenuContent<T extends object>({
  className,
  ...props
}: MenuProps<T>) {
  return (
    <AriaMenu
      {...props}
      data-slot="menu-content"
      className={composeRenderProps(className, (className) =>
        cn("grid max-h-72 gap-1 overflow-y-auto outline-none", className),
      )}
    />
  );
}

export function MenuItem<T extends object>({
  className,
  ...props
}: MenuItemProps<T>) {
  return (
    <AriaMenuItem
      {...props}
      data-slot="menu-item"
      className={composeRenderProps(className, (className) =>
        cn(
          "flex min-h-11 cursor-pointer items-center gap-2.5 rounded-md px-3 py-2 text-[13px] text-foreground outline-none hover:bg-muted data-[focused]:bg-muted data-[focus-visible]:-outline-offset-2 data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring data-[selected]:bg-accent data-[selected]:text-accent-foreground data-[disabled]:cursor-default data-[disabled]:opacity-50",
          className,
        ),
      )}
    />
  );
}

export function MenuSeparator({ className, ...props }: SeparatorProps) {
  return (
    <Separator
      {...props}
      data-slot="menu-separator"
      className={cn("border-t border-border/70", className)}
    />
  );
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost: "text-foreground hover:bg-muted data-[pressed]:bg-muted",
      destructive:
        "bg-destructive text-white shadow-[var(--shadow-card)] hover:brightness-95 data-[pressed]:brightness-95 dark:bg-destructive/60",
      nav: "text-foreground hover:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-[13px]",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
      nav: "h-9 w-full justify-center px-0 text-xs sm:justify-start sm:px-2.5",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      whileTap={isStatic || reduceMotion ? undefined : { scale: 0.96 }}
      transition={{ type: "spring", duration: 0.3, bounce: 0 }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}
